@php
use App\Support\Format as F;
$total = $balances->sum('balance'); $available = $balances->sum('available'); $realized = $balances->sum('realized');
$open = $allPositions->where('section','Current positions')->where('state','!=','Closed'); $active = $clients->where('archived', false);
$unrealized = $open->sum('pnl');
$combinedPnl = $realized + $unrealized;
$months = request('range') === '12' ? 12 : 6;
$chart = collect(range(0,$months-1))->map(function($i) use($months,$allDeposits,$allWithdrawals) {
 $month = now()->startOfMonth()->subMonths($months-1-$i); $key=$month->format('Y-m');
 return ['label'=>$month->format('M'),'deposit'=>$allDeposits->filter(fn($d)=>$d->status==='Completed' && $d->date->format('Y-m')===$key)->sum('amount'),'withdrawal'=>$allWithdrawals->filter(fn($w)=>$w->status==='Approved' && $w->created_at->format('Y-m')===$key)->sum('amount')];
});
$ceiling = max(1000000,ceil($chart->flatMap(fn($m)=>[$m['deposit'],$m['withdrawal']])->max()/1000000)*1000000);
$colors = ['#087f5b','#16a6a1','#4a91d5','#8b70ce','#d17a3f','#68834a'];
$allocationCategories = \App\Services\Ledger::CATEGORIES;
if ($allPositions->contains('category', \App\Services\Ledger::LEGACY_CATEGORY)) $allocationCategories[] = \App\Services\Ledger::LEGACY_CATEGORY;
$allocation = collect($allocationCategories)->map(fn($c)=>$open->where('category',$c)->sum(fn($p)=>$p->entry_price*$p->quantity));
$sum = $allocation->sum(); $stop=0; $gradient=[];
foreach($allocation as $i=>$value) { $start=$stop; $stop += $sum ? $value/$sum*100 : 0; $gradient[]=$colors[$i].' '.$start.'% '.$stop.'%'; }
$expiryToday = now()->timezone('Asia/Kolkata')->toDateString();
$expiryWarningEnd = now()->timezone('Asia/Kolkata')->addDays(\App\Services\Ledger::EXPIRY_WARNING_DAYS)->toDateString();
$expiryWatch = $allPositions->filter(fn($position) => in_array($position->category,\App\Services\Ledger::EXPIRY_CATEGORIES,true)
    && $position->expiry_date
    && $position->section!=='Last trades'
    && $position->state!=='Closed'
    && $position->expiry_date->format('Y-m-d') <= $expiryWarningEnd)
    ->sortBy(fn($position) => $position->expiry_date->format('Y-m-d'));
$pending=$allWithdrawals->where('status','Pending');
@endphp
